// Assumes 'file_fd' is an open file descriptor
const char *attr_to_remove = "user.revision_id";
int status;

// Remove extended attribute by file descriptor
status = fremovexattr(file_fd, attr_to_remove);

if (status == -1) {
    // Check for common failure modes
    if (errno == ENODATA) {
        // Attribute did not exist
    } else if (errno == ENOTSUP) {
        // XATTRs unsupported on filesystem
    } else {
        // EPERM, EFAULT, etc.
    }
}
// status == 0 on successful removal
